    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/flows`);
    await page.getByRole("checkbox", { name: "Select all" }).click();
    await expect(page.getByRole("button", { name: "Delete selected flows" })).toBeVisible();
    await page.getByRole("button", { name: "Delete selected flows" }).click();
    await expect(page.getByRole("heading", { name: "Delete 2 flows?" })).toBeVisible();
    await expect(page.getByRole("button", { name: "Delete" })).toBeVisible();
    await page.getByRole("button", { name: "Delete" }).click();
    await expect(page.getByRole("heading", { name: "Run a flow to get started" })).toBeVisible();
